/**
 * Codegen: engine catalog → TypeScript modules.
 *
 * Reads `engine/catalog.snapshot.json` (generated by the Rust engine)
 * and produces per-file directory structures:
 *
 *   - `src/generated/catalog/` — per-type node info + per-processor definitions
 *   - `src/generated/schemas/` — per-processor Zod schemas
 *   - `src/generated/engineSchemaEntries.ts` — auto-assembled NODE_SCHEMAS + NODE_PARAM_FIELDS
 *   - `src/generated/definitionSchema.ts` — JSON Schema for `.bnto.json` files
 *   - `src/generated/formatVersion.ts` — catalog version string
 *   - `packages/@bnto/backend/convex/_helpers/nodeTypeLabels.ts` — label map for Convex
 *   - `packages/@bnto/i18n/src/generated/nodes.json` — i18n strings
 *
 * Adding a new node type produces NEW per-type files + append-only barrel updates.
 * No monolithic files to regenerate, no merge conflicts.
 *
 * The Rust engine is the single source of truth for ALL node metadata.
 * Run via: `task nodes:generate` or `npx tsx scripts/generate-from-catalog.ts`
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync } from "node:fs";
import { resolve, dirname } from "node:path";

// --- Paths ---

const ROOT = resolve(dirname(import.meta.url.replace("file://", "")), "../../../..");
const CATALOG_PATH = resolve(ROOT, "engine/catalog.snapshot.json");
const GENERATED_DIR = resolve(ROOT, "packages/@bnto/nodes/src/generated");
const CATALOG_DIR = resolve(GENERATED_DIR, "catalog");
const NODE_TYPES_DIR = resolve(CATALOG_DIR, "nodeTypes");
const PROCESSORS_DIR = resolve(CATALOG_DIR, "processors");
const SCHEMAS_DIR = resolve(GENERATED_DIR, "schemas");
const DEF_SCHEMA_OUTPUT = resolve(GENERATED_DIR, "definitionSchema.ts");
const FORMAT_VERSION_OUTPUT = resolve(GENERATED_DIR, "formatVersion.ts");
const ENGINE_SCHEMA_ENTRIES_OUTPUT = resolve(GENERATED_DIR, "engineSchemaEntries.ts");
const DOCS_DIR = resolve(ROOT, "packages/@bnto/nodes/docs");
const CONVEX_LABELS_OUTPUT = resolve(
  ROOT,
  "packages/@bnto/backend/convex/_helpers/nodeTypeLabels.ts",
);
const I18N_STRINGS_OUTPUT = resolve(ROOT, "packages/@bnto/i18n/src/generated/nodes.json");

// Legacy files to clean up
const LEGACY_CATALOG = resolve(GENERATED_DIR, "catalog.ts");
const LEGACY_SCHEMAS = resolve(GENERATED_DIR, "schemas.ts");
const LEGACY_NODE_TYPES = resolve(GENERATED_DIR, "nodeTypes.ts");

// --- Types matching engine/catalog.snapshot.json schema ---

interface CatalogEnvelope {
  version: string;
  nodeTypes: RawNodeType[];
  processors: RawProcessor[];
  definitionSchema?: Record<string, unknown>;
}

interface RawNodeType {
  name: string;
  label: string;
  description: string;
  category: string;
  isContainer: boolean;
  platforms: string[];
  icon: string;
}

interface RawProcessor {
  nodeType: string;
  name: string;
  description: string;
  category: string;
  accepts: string[];
  platforms: string[];
  parameters: RawParameter[];
  inputCardinality?: string;
}

interface RawParameter {
  name: string;
  label: string;
  description: string;
  paramType: { type: string; options?: string[] };
  default?: unknown;
  constraints?: { min?: number; max?: number; required?: boolean };
  placeholder?: string;
  surfaceable?: boolean;
}

// --- Read catalog ---

const raw = readFileSync(CATALOG_PATH, "utf-8");
const catalog: CatalogEnvelope = JSON.parse(raw);

// --- Helpers ---

const HEADER = `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 * Run \`task nodes:generate\` to regenerate after engine changes.
 * Engine catalog v${catalog.version}
 */`;

function indent(s: string, n: number): string {
  const pad = "  ".repeat(n);
  return s
    .split("\n")
    .map((line) => (line.trim() ? pad + line : line))
    .join("\n");
}

function serializeValue(v: unknown): string {
  if (v === null || v === undefined) return "undefined";
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  return JSON.stringify(v);
}

/** Convert kebab-case to camelCase. */
function toCamelCase(s: string): string {
  return s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/** Convert kebab-case to PascalCase. */
function toPascalCase(s: string): string {
  const camel = toCamelCase(s);
  return camel.charAt(0).toUpperCase() + camel.slice(1);
}

/** Write file only if content changed (avoids unnecessary git diffs). */
function writeIfChanged(path: string, content: string): boolean {
  if (existsSync(path)) {
    const existing = readFileSync(path, "utf-8");
    if (existing === content) return false;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content, "utf-8");
  return true;
}

/** Remove files in a directory that aren't in the expected set. */
function cleanStaleFiles(dir: string, expectedFiles: Set<string>): void {
  if (!existsSync(dir)) return;
  for (const file of readdirSync(dir)) {
    if (!expectedFiles.has(file)) {
      rmSync(resolve(dir, file));
    }
  }
}

// =============================================================================
// Phase 1: Per-type node info files (catalog/nodeTypes/*.ts)
// =============================================================================

function generateNodeTypeFile(t: RawNodeType): string {
  const browserCapable = t.platforms.includes("browser");
  return `${HEADER}

import type { NodeTypeInfo } from "../types";

/** Node type info for ${t.name}. */
export const ${toCamelCase(t.name)}NodeType: NodeTypeInfo = {
  name: ${JSON.stringify(t.name)},
  label: ${JSON.stringify(t.label)},
  description: ${JSON.stringify(t.description)},
  category: ${JSON.stringify(t.category)},
  isContainer: ${t.isContainer},
  browserCapable: ${browserCapable},
  icon: ${JSON.stringify(t.icon)},
};
`;
}

function generateNodeTypesBarrel(): string {
  const types = catalog.nodeTypes;
  const sorted = [...types].sort((a, b) => a.name.localeCompare(b.name));

  const imports = sorted
    .map((t) => `import { ${toCamelCase(t.name)}NodeType } from "./${toCamelCase(t.name)}";`)
    .join("\n");

  const nodeTypesEntries = sorted
    .map((t) => `  ${toCamelCase(t.name)}: ${JSON.stringify(t.name)}`)
    .join(",\n");

  const nodeTypeInfoEntries = sorted
    .map((t) => `  ${JSON.stringify(t.name)}: ${toCamelCase(t.name)}NodeType`)
    .join(",\n");

  return `${HEADER}

import type { NodeTypeName, NodeTypeInfo } from "../types";

${imports}

/**
 * All registered node type names.
 * Maps camelCase keys to kebab-case type name strings.
 */
export const NODE_TYPES = {
${nodeTypesEntries},
} as const;

/** All node type names as a readonly array. */
export const NODE_TYPE_NAMES: readonly NodeTypeName[] = Object.values(NODE_TYPES) as NodeTypeName[];

/**
 * Metadata for all registered node types.
 * Maps node type name → info.
 */
export const NODE_TYPE_INFO: Record<NodeTypeName, NodeTypeInfo> = {
${nodeTypeInfoEntries},
} as const satisfies Record<NodeTypeName, NodeTypeInfo>;
`;
}

// =============================================================================
// Phase 1: Per-processor files (catalog/processors/*.ts)
// =============================================================================

function generateParamLiteral(p: RawParameter): string {
  const lines: string[] = [];
  lines.push("{");
  lines.push(`  name: ${JSON.stringify(p.name)},`);
  lines.push(`  label: ${JSON.stringify(p.label)},`);
  lines.push(`  description: ${JSON.stringify(p.description)},`);

  if (p.paramType.options) {
    lines.push(`  type: "enum" as const,`);
    lines.push(`  options: ${JSON.stringify(p.paramType.options)} as const,`);
  } else {
    lines.push(`  type: ${JSON.stringify(p.paramType.type)} as const,`);
  }

  if (p.default !== undefined) {
    lines.push(`  default: ${serializeValue(p.default)},`);
  }
  if (p.constraints) {
    const parts: string[] = [];
    if (p.constraints.min !== undefined) parts.push(`min: ${p.constraints.min}`);
    if (p.constraints.max !== undefined) parts.push(`max: ${p.constraints.max}`);
    if (p.constraints.required !== undefined) parts.push(`required: ${p.constraints.required}`);
    lines.push(`  constraints: { ${parts.join(", ")} },`);
  }
  if (p.placeholder !== undefined) {
    lines.push(`  placeholder: ${JSON.stringify(p.placeholder)},`);
  }
  if (p.surfaceable === false) {
    lines.push(`  surfaceable: false,`);
  }
  lines.push("}");
  return lines.join("\n");
}

function generateProcessorFile(p: RawProcessor): string {
  const params = p.parameters.map((param) => indent(generateParamLiteral(param), 1)).join(",\n");
  const cardinality = p.inputCardinality ?? "perFile";

  return `${HEADER}

import type { ProcessorDef } from "../types";

/** Processor definition for ${p.nodeType}. */
export const ${toCamelCase(p.nodeType)}Processor: ProcessorDef = {
  nodeType: ${JSON.stringify(p.nodeType)},
  name: ${JSON.stringify(p.name)},
  description: ${JSON.stringify(p.description)},
  category: ${JSON.stringify(p.category)},
  accepts: ${JSON.stringify(p.accepts)} as const,
  platforms: ${JSON.stringify(p.platforms)} as const,
  parameters: [
${params},
  ],
  inputCardinality: ${JSON.stringify(cardinality)} as const,
};
`;
}

function generateProcessorsBarrel(): string {
  const sorted = [...catalog.processors].sort((a, b) => a.nodeType.localeCompare(b.nodeType));

  const imports = sorted
    .map(
      (p) => `import { ${toCamelCase(p.nodeType)}Processor } from "./${toCamelCase(p.nodeType)}";`,
    )
    .join("\n");

  const entries = sorted.map((p) => `  ${toCamelCase(p.nodeType)}Processor`).join(",\n");

  return `${HEADER}

import type { ProcessorDef } from "../types";

${imports}

export const PROCESSORS: readonly ProcessorDef[] = [
${entries},
] as const;
`;
}

// =============================================================================
// Phase 1: Shared types + helpers + iteration modes (catalog/)
// =============================================================================

function generateCatalogTypes(): string {
  const categories = [...new Set(catalog.nodeTypes.map((t) => t.category))].sort();
  const categoryUnion = categories.map((c) => `"${c}"`).join(" | ");

  const sorted = [...catalog.nodeTypes].sort((a, b) => a.name.localeCompare(b.name));
  const nameUnion = sorted.map((t) => `  | ${JSON.stringify(t.name)}`).join("\n");

  return `${HEADER}

/** Union of all valid node type name strings. */
export type NodeTypeName =
${nameUnion};

/** Node category for grouping in the UI and documentation. */
export type NodeCategory = ${categoryUnion};

/** Metadata describing a node type's behavior and capabilities. */
export interface NodeTypeInfo {
  /** The node type name as used in \`.bnto.json\` definitions. */
  name: NodeTypeName;
  /** Human-readable display label. */
  label: string;
  /** One-sentence description of what the node does. */
  description: string;
  /** Category for grouping. */
  category: NodeCategory;
  /** Whether this node can contain child nodes (group, loop). */
  isContainer: boolean;
  /** Whether this node type is available for browser execution. */
  browserCapable: boolean;
  /** Lucide icon name for visual consumers. */
  icon: string;
}

export type ParamType = "number" | "string" | "boolean" | "enum" | "object" | "file";

export interface ProcessorParam {
  readonly name: string;
  readonly label: string;
  readonly description: string;
  readonly type: ParamType;
  readonly options?: readonly string[];
  readonly default?: unknown;
  readonly constraints?: {
    readonly min?: number;
    readonly max?: number;
    readonly required?: boolean;
  };
  readonly placeholder?: string;
  /** Whether this param is eligible for surfacing in container config panels. Defaults to true. */
  readonly surfaceable?: boolean;
}

export interface ProcessorDef {
  readonly nodeType: string;
  readonly name: string;
  readonly description: string;
  readonly category: string;
  readonly accepts: readonly string[];
  readonly platforms: readonly string[];
  readonly parameters: readonly ProcessorParam[];
  readonly inputCardinality: "perFile" | "batch";
}
`;
}

function generateHelpers(): string {
  return `${HEADER}

import type { ProcessorDef, ProcessorParam } from "./types";
import { PROCESSORS } from "./processors";

/** Map keyed by nodeType for O(1) lookup. */
export const PROCESSOR_MAP = new Map<string, ProcessorDef>(
  PROCESSORS.map((p) => [p.nodeType, p]),
);

/** Get the engine defaults for a node type. */
export function getProcessorDefaults(
  nodeType: string,
): Record<string, unknown> {
  const proc = PROCESSOR_MAP.get(nodeType);
  if (!proc) return {};
  const defaults: Record<string, unknown> = {};
  for (const param of proc.parameters) {
    if (param.default !== undefined) {
      defaults[param.name] = param.default;
    }
  }
  return defaults;
}

/** Get the engine constraints for a specific parameter. */
export function getParamConstraints(
  nodeType: string,
  paramName: string,
): ProcessorParam["constraints"] | undefined {
  const proc = PROCESSOR_MAP.get(nodeType);
  if (!proc) return undefined;
  const param = proc.parameters.find((p) => p.name === paramName);
  return param?.constraints;
}

/** Get the accepted MIME types for a node type. */
export function getProcessorAccepts(
  nodeType: string,
): readonly string[] {
  const proc = PROCESSOR_MAP.get(nodeType);
  return proc?.accepts ?? [];
}
`;
}

function generateIterationModes(): string | null {
  const modes = extractIterationModes();
  if (!modes) return null;

  return `${HEADER}

/** Valid iteration modes from the engine's definition schema. */
export const ITERATION_MODES = ${JSON.stringify(modes)} as const;

/** Union type of valid iteration mode strings. */
export type IterationModeValue = (typeof ITERATION_MODES)[number];
`;
}

function extractIterationModes(): string[] | null {
  if (!catalog.definitionSchema) return null;
  const defs = (catalog.definitionSchema as Record<string, unknown>).$defs as
    | Record<string, unknown>
    | undefined;
  if (!defs) return null;
  const ps = defs.PipelineSettings as
    | { properties?: { iteration?: { enum?: string[] } } }
    | undefined;
  return ps?.properties?.iteration?.enum ?? null;
}

function generateCatalogBarrel(): string {
  const hasIterationModes = extractIterationModes() !== null;

  return `${HEADER}

// Types
export type { NodeTypeName, NodeCategory, NodeTypeInfo, ParamType, ProcessorParam, ProcessorDef } from "./types";

// Node types
export { NODE_TYPES, NODE_TYPE_NAMES, NODE_TYPE_INFO } from "./nodeTypes";

// Processors
export { PROCESSORS } from "./processors";

// Lookup helpers
export { PROCESSOR_MAP, getProcessorDefaults, getParamConstraints, getProcessorAccepts } from "./processorLookups";
${
  hasIterationModes
    ? `
// Iteration modes
export { ITERATION_MODES } from "./iterationModes";
export type { IterationModeValue } from "./iterationModes";`
    : ""
}
`;
}

// =============================================================================
// Phase 2: Per-processor Zod schema files (schemas/*.ts)
// =============================================================================

/** Generate a single Zod field from a RawParameter. */
function generateZodField(param: RawParameter): string {
  const name = param.name;
  let zodChain: string;

  switch (param.paramType.type) {
    case "number": {
      zodChain = "z.number()";
      if (param.constraints?.min !== undefined) {
        zodChain += `.min(${param.constraints.min})`;
      }
      if (param.constraints?.max !== undefined) {
        zodChain += `.max(${param.constraints.max})`;
      }
      break;
    }
    case "string": {
      zodChain = "z.string()";
      break;
    }
    case "boolean": {
      zodChain = "z.boolean()";
      break;
    }
    case "enum": {
      const options = param.paramType.options ?? [];
      zodChain = `z.enum(${JSON.stringify(options)} as const)`;
      break;
    }
    case "object": {
      zodChain = "z.record(z.string())";
      break;
    }
    case "file": {
      zodChain = "z.string()";
      break;
    }
    default: {
      zodChain = "z.unknown()";
    }
  }

  if (param.constraints?.required) {
    if (param.default !== undefined) {
      zodChain += `.default(${serializeValue(param.default)})`;
    }
  } else {
    zodChain += ".optional()";
    if (param.default !== undefined) {
      zodChain += `.default(${serializeValue(param.default)})`;
    }
  }

  return `  ${name}: ${zodChain}`;
}

/** Generate NodeParam entry for a parameter. */
function generateNodeParam(param: RawParameter): string {
  const lines: string[] = [];
  lines.push(`    ${param.name}: {`);
  lines.push(`      label: ${JSON.stringify(param.label)},`);
  lines.push(`      description: ${JSON.stringify(param.description)},`);
  if (param.placeholder !== undefined) {
    lines.push(`      placeholder: ${JSON.stringify(param.placeholder)},`);
  }
  if (param.surfaceable === false) {
    lines.push(`      surfaceable: false,`);
  }
  lines.push(`    },`);
  return lines.join("\n");
}

function generateSchemaFile(proc: RawProcessor): string {
  const nodeType = proc.nodeType;
  const camelName = toCamelCase(nodeType);
  const pascalName = toPascalCase(nodeType);

  const zodFields = proc.parameters.map((p) => `  ${generateZodField(p)},`);

  const uiMetaEntries = proc.parameters.map((p) => generateNodeParam(p));

  return `${HEADER}

import { z } from "zod";
import type { NodeSchema } from "../../schemas/types";

/** Zod schema for ${nodeType} node parameters. */
export const ${camelName}ParamsSchema = z.object({
${zodFields.join("\n")}
});

/** Inferred TypeScript type for ${nodeType} node parameters. */
export type ${pascalName}Params = z.infer<typeof ${camelName}ParamsSchema>;

/** Full schema definition for the ${nodeType} node type. */
export const ${camelName}NodeSchema: NodeSchema = {
  nodeType: ${JSON.stringify(nodeType)},
  schemaVersion: 1,
  schema: ${camelName}ParamsSchema,
  params: {
${uiMetaEntries.join("\n")}
  },
};
`;
}

function generateSchemasBarrel(): string {
  const sorted = [...catalog.processors].sort((a, b) => a.nodeType.localeCompare(b.nodeType));

  const reexports = sorted.map((p) => {
    const camelName = toCamelCase(p.nodeType);
    const pascalName = toPascalCase(p.nodeType);
    return `export { ${camelName}ParamsSchema, ${camelName}NodeSchema } from "./${camelName}";
export type { ${pascalName}Params } from "./${camelName}";`;
  });

  return `${HEADER}

${reexports.join("\n")}
`;
}

// =============================================================================
// Phase 3: Engine schema entries (auto-assembled registry)
// =============================================================================

function generateEngineSchemaEntries(): string {
  const sorted = [...catalog.processors].sort((a, b) => a.nodeType.localeCompare(b.nodeType));

  const schemaImports = sorted
    .map(
      (p) =>
        `import { ${toCamelCase(p.nodeType)}NodeSchema } from "./schemas/${toCamelCase(p.nodeType)}";`,
    )
    .join("\n");

  const schemaEntries = sorted
    .map((p) => `  ${JSON.stringify(p.nodeType)}: ${toCamelCase(p.nodeType)}NodeSchema`)
    .join(",\n");

  const fieldsEntries = sorted.map((p) => `  ${JSON.stringify(p.nodeType)}: {}`).join(",\n");

  return `${HEADER}

import type { NodeSchema } from "../schemas/types";
import type { NodeParamFields } from "../schemas/types";

${schemaImports}

/**
 * Engine-backed schema entries — auto-assembled from generated per-type files.
 * Merged with hand-written schemas in schemas/registry.ts.
 */
export const ENGINE_NODE_SCHEMAS: Record<string, NodeSchema> = {
${schemaEntries},
};

/**
 * Default (empty) field configs for engine-backed types.
 * Hand-written overrides in schemas/{type}.ts take precedence.
 */
export const ENGINE_NODE_PARAM_FIELDS: Record<string, NodeParamFields> = {
${fieldsEntries},
};
`;
}

// =============================================================================
// Unchanged generators (definitionSchema, docs, convex labels, i18n, etc.)
// =============================================================================

function generateDefinitionSchemaFile(): string {
  if (!catalog.definitionSchema) {
    return `/**
 * Definition JSON Schema — NOT AVAILABLE (engine did not include it).
 */
export const DEFINITION_JSON_SCHEMA = null;
`;
  }

  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * JSON Schema (Draft 2020-12) for \`.bnto.json\` definition files.
 * Use this to validate definition files in any language or tool
 * that supports JSON Schema (VS Code, ajv, jsonschema, etc.).
 *
 * Run \`task nodes:generate\` to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

/** JSON Schema for .bnto.json definition files. */
export const DEFINITION_JSON_SCHEMA = ${JSON.stringify(catalog.definitionSchema, null, 2)} as const;
`;
}

function formatRange(p: RawParameter): string {
  if (p.constraints?.min !== undefined && p.constraints?.max !== undefined) {
    return `${p.constraints.min}–${p.constraints.max}`;
  }
  if (p.constraints?.min !== undefined) return `≥ ${p.constraints.min}`;
  if (p.constraints?.max !== undefined) return `≤ ${p.constraints.max}`;
  return "—";
}

function formatDefault(p: RawParameter): string {
  if (p.default === undefined) return "—";
  return String(p.default);
}

function generateNodeReadme(nodeType: RawNodeType, processor: RawProcessor | undefined): string {
  const lines: string[] = [];
  const platforms = nodeType.platforms.join(", ") || "none";

  lines.push(`# ${nodeType.label} Node`);
  lines.push("");
  lines.push(`> ${nodeType.description}`);
  lines.push("");
  lines.push(
    `**Category:** ${nodeType.category} | **Platforms:** ${platforms} | **Container:** ${nodeType.isContainer ? "yes" : "no"}`,
  );
  lines.push("");

  if (processor) {
    if (processor.accepts.length > 0) {
      lines.push("## Accepts");
      lines.push("");
      for (const mime of processor.accepts) {
        lines.push(`- \`${mime}\``);
      }
      lines.push("");
    }

    if (processor.parameters.length > 0) {
      lines.push("## Parameters");
      lines.push("");
      lines.push("| Parameter | Type | Default | Range | Description |");
      lines.push("|-----------|------|---------|-------|-------------|");

      for (const param of processor.parameters) {
        const type = param.paramType.options ? "enum" : param.paramType.type;
        const range = param.paramType.options
          ? param.paramType.options.join(", ")
          : formatRange(param);
        lines.push(
          `| ${param.name} | ${type} | ${formatDefault(param)} | ${range} | ${param.description} |`,
        );
      }
      lines.push("");
    }

    const exampleParams: Record<string, unknown> = {};
    for (const param of processor.parameters) {
      if (param.default !== undefined) {
        exampleParams[param.name] = param.default;
      } else if (param.constraints?.required) {
        exampleParams[param.name] = param.paramType.options?.[0] ?? `<${param.paramType.type}>`;
      }
    }

    lines.push("## Configuration Example");
    lines.push("");
    lines.push("```json");
    lines.push(`{`);
    lines.push(`  "type": ${JSON.stringify(nodeType.name)},`);
    lines.push(
      `  "parameters": ${JSON.stringify(exampleParams, null, 4)
        .split("\n")
        .map((l, i) => (i === 0 ? l : "  " + l))
        .join("\n")}`,
    );
    lines.push(`}`);
    lines.push("```");
    lines.push("");
  }

  lines.push("---");
  lines.push("");
  lines.push(
    `*Auto-generated from engine catalog v${catalog.version}. Run \`task nodes:generate\` to regenerate.*`,
  );
  lines.push("");

  return lines.join("\n");
}

function generateAllNodeReadmes(): void {
  mkdirSync(DOCS_DIR, { recursive: true });

  const processorByType = new Map<string, RawProcessor>();
  for (const p of catalog.processors) {
    processorByType.set(p.nodeType, p);
  }

  for (const nodeType of catalog.nodeTypes) {
    const processor = processorByType.get(nodeType.name);
    const readme = generateNodeReadme(nodeType, processor);
    const filename = resolve(DOCS_DIR, `${nodeType.name}.md`);
    writeFileSync(filename, readme, "utf-8");
  }

  console.log(`Generated ${catalog.nodeTypes.length} node READMEs in ${DOCS_DIR}`);
}

function generateConvexLabelsFile(): string {
  const entries = catalog.nodeTypes
    .filter((t) => !t.isContainer && t.category !== "io")
    .map((t) => `  ${JSON.stringify(t.name)}: ${JSON.stringify(t.label)},`)
    .join("\n");

  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * Convex can't import from @bnto/nodes (bundling constraint), so this
 * file is generated alongside the main catalog. Run \`task nodes:generate\`
 * to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

/** Node type name → display label for processing nodes (excludes I/O and containers). */
export const NODE_TYPE_LABELS: Record<string, string> = {
${entries}
};
`;
}

function generateFormatVersionFile(): string {
  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * The catalog format version, extracted from the engine catalog.
 * Run \`task nodes:generate\` to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

/** The format version from the engine catalog. */
export const CATALOG_FORMAT_VERSION = ${JSON.stringify(catalog.version)};
`;
}

function generateI18nStringsFile(): string {
  const nodeTypes: Record<string, Record<string, string>> = {};
  const params: Record<string, Record<string, Record<string, string>>> = {};
  const categories: Record<string, string> = {};

  for (const nt of catalog.nodeTypes) {
    const key = toCamelCase(nt.name);
    nodeTypes[key] = { label: nt.label, description: nt.description };
    if (!categories[nt.category]) {
      categories[nt.category] = nt.category.charAt(0).toUpperCase() + nt.category.slice(1);
    }
  }

  for (const proc of catalog.processors) {
    const key = toCamelCase(proc.nodeType);
    if (proc.parameters.length === 0) continue;
    const paramEntries: Record<string, Record<string, string>> = {};
    for (const p of proc.parameters) {
      const entry: Record<string, string> = { label: p.label, description: p.description };
      if (p.placeholder) entry.placeholder = p.placeholder;
      paramEntries[p.name] = entry;
    }
    params[key] = paramEntries;
  }

  const output = {
    _generatedBy: `generate-from-catalog.ts — DO NOT EDIT manually. Engine catalog v${catalog.version}`,
    nodeTypes,
    params,
    categories,
  };

  return JSON.stringify(output, null, 2) + "\n";
}

// =============================================================================
// Assemble and write
// =============================================================================

let filesWritten = 0;
let filesUnchanged = 0;

function write(path: string, content: string): void {
  if (writeIfChanged(path, content)) {
    filesWritten++;
  } else {
    filesUnchanged++;
  }
}

// Create directories
mkdirSync(NODE_TYPES_DIR, { recursive: true });
mkdirSync(PROCESSORS_DIR, { recursive: true });
mkdirSync(SCHEMAS_DIR, { recursive: true });

// --- catalog/nodeTypes/*.ts ---
const expectedNodeTypeFiles = new Set<string>(["index.ts"]);
for (const t of catalog.nodeTypes) {
  const filename = `${toCamelCase(t.name)}.ts`;
  expectedNodeTypeFiles.add(filename);
  write(resolve(NODE_TYPES_DIR, filename), generateNodeTypeFile(t));
}
write(resolve(NODE_TYPES_DIR, "index.ts"), generateNodeTypesBarrel());
cleanStaleFiles(NODE_TYPES_DIR, expectedNodeTypeFiles);

// --- catalog/processors/*.ts ---
const expectedProcessorFiles = new Set<string>(["index.ts"]);
for (const p of catalog.processors) {
  const filename = `${toCamelCase(p.nodeType)}.ts`;
  expectedProcessorFiles.add(filename);
  write(resolve(PROCESSORS_DIR, filename), generateProcessorFile(p));
}
write(resolve(PROCESSORS_DIR, "index.ts"), generateProcessorsBarrel());
cleanStaleFiles(PROCESSORS_DIR, expectedProcessorFiles);

// --- catalog/types.ts, helpers.ts, iterationModes.ts, index.ts ---
const expectedCatalogFiles = new Set<string>([
  "types.ts",
  "processorLookups.ts",
  "index.ts",
  "nodeTypes",
  "processors",
]);
write(resolve(CATALOG_DIR, "types.ts"), generateCatalogTypes());
write(resolve(CATALOG_DIR, "processorLookups.ts"), generateHelpers());

const iterationModesContent = generateIterationModes();
if (iterationModesContent) {
  expectedCatalogFiles.add("iterationModes.ts");
  write(resolve(CATALOG_DIR, "iterationModes.ts"), iterationModesContent);
}

write(resolve(CATALOG_DIR, "index.ts"), generateCatalogBarrel());

// --- schemas/*.ts ---
const expectedSchemaFiles = new Set<string>(["index.ts"]);
for (const p of catalog.processors) {
  const filename = `${toCamelCase(p.nodeType)}.ts`;
  expectedSchemaFiles.add(filename);
  write(resolve(SCHEMAS_DIR, filename), generateSchemaFile(p));
}
write(resolve(SCHEMAS_DIR, "index.ts"), generateSchemasBarrel());
cleanStaleFiles(SCHEMAS_DIR, expectedSchemaFiles);

// --- engineSchemaEntries.ts ---
write(ENGINE_SCHEMA_ENTRIES_OUTPUT, generateEngineSchemaEntries());

// --- Unchanged single-file outputs ---
write(DEF_SCHEMA_OUTPUT, generateDefinitionSchemaFile());
write(FORMAT_VERSION_OUTPUT, generateFormatVersionFile());
write(CONVEX_LABELS_OUTPUT, generateConvexLabelsFile());
mkdirSync(dirname(I18N_STRINGS_OUTPUT), { recursive: true });
write(I18N_STRINGS_OUTPUT, generateI18nStringsFile());
generateAllNodeReadmes();

// --- Clean up legacy monolithic files ---
for (const legacy of [LEGACY_CATALOG, LEGACY_SCHEMAS, LEGACY_NODE_TYPES]) {
  try {
    rmSync(legacy);
    console.log(`Removed legacy ${legacy}`);
  } catch {
    // Doesn't exist, that's fine
  }
}

// --- Summary ---
console.log(`\nCodegen complete (${filesWritten} written, ${filesUnchanged} unchanged):`);
console.log(`  catalog/nodeTypes/ — ${catalog.nodeTypes.length} per-type files`);
console.log(`  catalog/processors/ — ${catalog.processors.length} per-processor files`);
console.log(`  schemas/ — ${catalog.processors.length} per-processor Zod schemas`);
console.log(
  `  engineSchemaEntries.ts — ${catalog.processors.length} auto-assembled registry entries`,
);
console.log(`  definitionSchema.ts — ${catalog.definitionSchema ? "included" : "NOT included"}`);
console.log(`  formatVersion.ts — v${catalog.version}`);
if (extractIterationModes()) {
  console.log(`  iterationModes.ts — ${extractIterationModes()!.join(", ")}`);
}
console.log(
  `  ${CONVEX_LABELS_OUTPUT} — ${catalog.nodeTypes.filter((t) => !t.isContainer && t.category !== "io").length} labels`,
);
console.log(`  ${I18N_STRINGS_OUTPUT} — i18n strings`);
